AR_ABD = {'عبد'}


def split_tokens(name):
    s = name.replace('\\u2019', "'").replace('\\u02bc', "'")
    s = re.sub(r"[.;/\\\\()\\[\\]\\"]", ' ', s)
    s = s.replace('-', ' ').replace('_', ' ')
    s = re.sub(r"'", '', s)
    parts = [p for p in s.split(',')]
    if len(parts) > 1 and any(p.strip() for p in parts[1:]):
        # "Family, Given" -> put the given part first
        s = ' '.join(parts[1:]) + ' ' + parts[0]
    else:
        s = ' '.join(parts)
    return [t for t in s.split() if t]


def _strip_article_prefix(tok_str):
    f = fold(tok_str)
    m = ARTICLE_RE.match(f)
    if m and len(f) - m.end() >= 3:
        return f[m.end():]
    return f


class ParsedName(object):
    __slots__ = ('core', 'pairs', 'single', 'ntok')

    def __init__(self, core):
        self.core = core
        self.ntok = len(core)
        self.single = core[0] if len(core) == 1 else None
        self.pairs = build_pairs(core)


def build_pairs(core):
    n = len(core)
    pairs = []
    if n < 2:
        return pairs
    if n == 2:
        pairs.append((core[0], core[1]))
        pairs.append((core[1], core[0]))
        return pairs
    a, z = core[0], core[-1]
    pairs.append((a, z))
    pairs.append((z, a))
    j_last = join_toks(core[-2], core[-1])
    pairs.append((a, j_last))
    pairs.append((j_last, a))
    j_first = join_toks(core[0], core[1])
    pairs.append((j_first, z))
    pairs.append((z, j_first))
    return pairs


PATRONYMIC_RE = re.compile(
    r'(?:vich|vitch|vitsch|witch|witsch|wich|vicz|wicz|vic|wic|'
    r'vna|wna|vnja|wnja)$')


def is_patronymic(folded):
    return bool(PATRONYMIC_RE.search(folded)) and len(folded) > 6


def _is_script(t):
    return bool(ARABIC_RE.search(t))


def parse_name(name, kind='individual'):
    toks = split_tokens(name)
    if not toks:
        return ParsedName([])
    folded = []
    for t in toks:
        if _is_script(t) or CYRILLIC_RE.search(t):
            folded.append(t)
        else:
            folded.append(fold(t))
    core = []
    i = 0
    n = len(folded)
    while i < n:
        low = folded[i]
        script = _is_script(low)
        if low in DROP_TOKENS:
            i += 1
            continue
        # arabic / western nasab: bin <father>
        if low in NASAB and i + 1 < n:
            remaining = n - (i + 2)
            if len(core) + remaining >= 2:
                j = i + 2
                # father may be an abd- compound: bin abd al-aziz
                fn = folded[i + 1]
                if (fn in ABD_EXACT or fn in AR_ABD or
                        (not _is_script(fn) and ABD_RE.match(fn))):
                    while j < n and folded[j] in PARTICLES and j + 1 < n:
                        j += 1
                    if j < n and n - (j + 1) >= 2:
                        j += 1
                i = j
                continue
            i += 1
            continue
        if len(low) == 1 and not script:
            i += 1
            continue
        if low in PARTICLES and i + 1 < n:
            # articles and nobiliary particles attach to the following word
            j = i
            pref = ''
            while j < n - 1 and folded[j] in PARTICLES and not _is_script(
                    folded[j]):
                pref += folded[j]
                j += 1
            if _is_script(folded[j]):
                folded[j] = folded[j]
            else:
                folded[j] = pref + folded[j]
            i = j
            continue
        if not script and is_patronymic(low):
            remaining = n - (i + 1)
            if len(core) + remaining >= 2:
                i += 1
                continue
        # abd- compounds
        if low in AR_ABD and i + 1 < n:
            core.append(('abd', folded[i + 1]))
            i += 2
            continue
        if not script and ABD_RE.match(low):
            if low in ABD_EXACT and i + 1 < n:
                nxt = folded[i + 1]
                if _is_script(nxt):
                    core.append(('abd', nxt))
                else:
                    core.append(('abd', _strip_article_prefix(nxt)))
                i += 2
                continue
            if len(low) > 5:
                rest = low[3:]
                if len(rest) >= 3:
                    core.append(('abd', rest))
                    i += 1
                    continue
        core.append(low)
        i += 1
    out = []
    for c in core:
        if isinstance(c, tuple):
            out.append(join_toks(get_tok('abd'), get_tok(c[1])))
        else:
            out.append(get_tok(c))
    return ParsedName(out)


