near = []
for row in cust:
    d = dec[row['customer_id']]
    if d['decision'] == 'MATCH':
        continue
    if (row.get('type') or 'individual') != 'individual':
        continue
    parsed = screen.parse_name(row['full_name'])
    if len(parsed.core) < 2:
        continue
    best = None
    for idx in eng.candidates(parsed):
        en = eng.person_names[idx]
        e = eng.entries[en.uid]
        if e.get('type') != 'individual':
            continue
        # score: how many of given/family correspond
        sc = 0
        for (g1, f1) in parsed.pairs:
            for (g2, f2) in en.parsed.pairs:
                s = 0
                if any(screen.tok_match(x, y) for x in screen.given_tok_set(g1)
                       for y in screen.given_tok_set(g2)):
                    s += 1
                if any(screen.tok_match(x, y) for x in screen.family_tok_set(f1)
                       for y in screen.family_tok_set(f2)):
                    s += 1
                sc = max(sc, s)
        ok, corr = screen.dob_check(row['dob'], e.get('dob', ''))
        if sc >= 1:
            if best is None or sc > best[0]:
                best = (sc, en.uid, en.raw, e.get('dob', ''), ok)
    if best and best[0] >= 1:
        near.append((row['customer_id'], row['full_name'], row['dob'], best))
print('near misses:', len(near))
