def best_key(t):
    return min(t.sk, key=len) if t.sk else ''


def ed(a, b):
    if abs(len(a) - len(b)) > 2:
        return 9
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def loose(t1, t2):
    if screen.tok_match(t1, t2):
        return 0
    best = 9
    for a in list(t1.sk)[:400]:
        for b in list(t2.sk)[:400]:
            d = ed(a, b)
            if d < best:
                best = d
                if best <= 1:
                    return best
    return best


