# -*- coding: utf-8 -*-
"""Consonant-skeleton matcher: find NO_MATCH customers a looser scheme hits."""
import csv, json, sys, collections, re
import screen

wl = json.load(open('/app/watchlist.json'))
eng = screen.Engine(wl)
path = sys.argv[1] if len(sys.argv) > 1 else '/app/customers.csv'
dec = {r['customer_id']: r for r in csv.DictReader(
    open(sys.argv[2] if len(sys.argv) > 2 else '/app/decisions.csv'))}

VOW = re.compile(r'[AIUaiu]')


def cons(t):
    return frozenset(VOW.sub('', k) for k in t.sk if len(VOW.sub('', k)) >= 2)


_cc = {}


def ccons(t):
    r = _cc.get(id(t))
    if r is None:
        r = cons(t)
        _cc[id(t)] = r
    return r


def cmatch(a, b):
    return not ccons(a).isdisjoint(ccons(b))


out = []
for r in csv.DictReader(open(path)):
    if (r['type'] or 'individual') != 'individual':
        continue
    if dec[r['customer_id']]['decision'] == 'MATCH':
        continue
    p = screen.parse_name(r['full_name'])
    if len(p.core) < 2:
