            for (g2, f2) in en.parsed.pairs:
                if not any(cmatch(x, y) for x in screen.given_tok_set(g1)
                           for y in screen.given_tok_set(g2)):
                    continue
                if not any(cmatch(x, y) for x in screen.family_tok_set(f1)
                           for y in screen.family_tok_set(f2)):
                    continue
                found = True
                break
            if found:
                break
        if found:
            out.append((r['customer_id'], r['full_name'], r['dob'], en.uid,
                        en.raw, e.get('dob', '')))
            break
print('consonant-loose near matches:', len(out))
for cid, nm, dob, uid, raw, edob in out[:int(sys.argv[3]) if len(sys.argv) > 3 else 60]:
    print('  %-9s %-40r %-11s -> %-10s %-40r %s' % (cid, nm, dob, uid, raw, edob))
