    """String level variants of one latin word."""
    guard = NICK
    stack = [w]
    seen = set()
    while stack:
        x = stack.pop()
        if x in seen or not x:
            continue
        seen.add(x)
        if len(x) > 4 and x[-1] == 'h':
            stack.append(x[:-1])
        if len(x) > 4 and x[-1] == 'e':
