# which always shows the doubled consonant (as-sabah -> assabah)
ARTICLE_RE = re.compile(
    r'^(?:[aeiou](?:sh|sch|ch)(?=sh|sch|ch)|[aeiou](l|d|n|r|s|t|z)(?=\1)|'
    r'a-?l|e-?l|u-?l|i-?l|o-?l)[- ]?')


